import test from 'node:test';
import assert from 'node:assert/strict';
import { evaluate, setupToState, lsq } from '../js/physics.js';
import { measurementStats, weightedLinearFit, experimentalMetrics, lmFit, modelMaker, SD_FLOOR } from '../js/analysis.js';
import { parseRaw, classifyHeader, cellsToLines } from '../js/import.js';

// Values generated by running the unmodified reference main/index.html functions.
const setup = { I: 1, dw: .5, d: 53.6, h1: 25, h2: 10, coordinateReference: 'centers',
  c1: { R: 46.25, m: 40, n: 5, last: 26, dir: 1, windingWidth: 20, plateThickness: 4 },
  c2: { R: 22.25, m: 11, n: 1, last: 11, dir: 1, windingWidth: 10, plateThickness: 4 } };
const near = (actual, expected, tol = 1e-9) => assert.ok(Math.abs(actual - expected) <= tol, `${actual} vs ${expected}`);

test('reference default Model 1, Model 2 and target at five x values', () => {
  const S = setupToState(setup), E = evaluate(S);
  const xs = [0, S.d / 4, S.d / 2, S.d * 3 / 4, S.d];
  const model1 = [25.44364710571231, 22.74363413861855, 17.17710087219595, 12.816571990886654, 10.151549702436709];
  const model2 = [24.959746824640686, 22.50311889524506, 17.249291946078007, 12.964796076066833, 10.239746615647519];
  const target = [25, 21.25, 17.5, 13.75, 10];
  xs.forEach((x, i) => { near(E.thin(x), model1[i]); near(E.total(x), model2[i]); near(S.h1 + (S.h2 - S.h1) * x / S.d, target[i]); });
  near(E.maxDev, 1.3512788059496685); near(E.rmsDev, .7693478987849387);
  near(E.nonlin, 1.1062142178491534); near(E.fit.a, -314.22422773264276);
  near(E.hAt0, model2[0]); near(E.hAtD, model2[4]);
});

test('outer-face coordinates keep the same coil physics while moving x = 0 and d to bobbin edges', () => {
  const legacy = evaluate(setupToState({ ...setup, d: 63 }));
  const outerSetup = { ...setup, d: 40, coordinateReference: 'outer' };
  const S = setupToState(outerSetup), E = evaluate(S);
  near(S.c1.xc, -.014);
  near(S.c2.xc, .049);
  near(S.c2EdgeOffset, .009);
  near(E.total(0), legacy.total(.014));
  near(E.total(.04), legacy.total(.054));
  near(E.hAt0, E.total(0));
  near(E.hAtD, E.total(.04));
  const lmBase = modelMaker(S, { k: 1, x0: 0, Hbg: 0, R1: setup.c1.R, R2: setup.c2.R, d: 40 });
  for (const xmm of [0, 4.5, 10, 23, 40]) near(lmBase(xmm), E.total(xmm / 1000));
  const widerGap = evaluate(setupToState({ ...outerSetup, d: 42 }));
  const lmWiderGap = modelMaker(S, { k: 1, x0: 0, Hbg: 0, R1: setup.c1.R, R2: setup.c2.R, d: 42 });
  for (const xmm of [0, 10, 20, 40]) near(lmWiderGap(xmm), widerGap.total(xmm / 1000));
});

const raw = [
  '14.0, 24.20, 24.26, 24.20', '17.2, 22.68, 22.63, 22.60',
  '20.4, 20.88, 20.88, 20.89', '23.6, 19.06, 18.96, 19.03',
  '26.8, 17.15, 17.22, 17.15', '29.9, 15.38, 15.33, 15.30',
  '33.1, 13.54, 13.56, 13.60', '36.3, 11.77, 11.81, 11.81',
  '39.5, 10.07, 10.00, 10.03'
].join('\n');

test('measurement grouping, sample STDEV and weighted LSQ match reference', () => {
  const { positions } = parseRaw(raw + '\n14.0, 24.20,');
  assert.equal(positions.length, 9);
  assert.equal(positions[0].readings.length, 4);
  const rows = parseRaw(raw).positions.map(p => ({ ...p, ...measurementStats(p.readings) }));
  near(rows[0].mean, 24.22); near(rows[0].sd, .03464101615137767);
  near(rows[2].sd, .005773502691896135);
  near(SD_FLOOR, .02886751345948129);
  const fit = weightedLinearFit(rows);
  near(fit.a, -563.4506592210854); near(fit.b, 32.2606304228908); near(fit.r2, .9997253631288192);
  near(lsq([0, .01, .02], [25, 20, 15], [3, 4, 5]).a, -500);
});

test('experimental target and model deviations retain their numerical values', () => {
  const S = setupToState(setup), E = evaluate(S);
  const rows = [{ x: 0, readings: [24.8, 24.9, 25] }, { x: 53.6, readings: [10.1, 10.2, 10.3] }]
    .map(p => ({ ...p, ...measurementStats(p.readings) }));
  const result = experimentalMetrics(rows, x => E.total(x / 1000), x => S.h1 + (S.h2 - S.h1) * x / setup.d, null);
  near(result.target.maxAbs, .2);
  near(result.target.at, 53.6);
  near(result.target.rmse, .15811388300841897);
  near(result.model.rmse, .050741878710176304);
});

test('LM fit matches reference example with k and R1 free', () => {
  const rows = parseRaw(raw).positions.map(p => ({ ...p, ...measurementStats(p.readings) }));
  const fit = lmFit(setupToState(setup), rows, ['k', 'R1'], true, 80);
  near(fit.P.k, .9267703152101859); near(fit.P.R1, 35.203802779195435);
  near(fit.se[0], .011374081792024631); near(fit.se[1], 1.0572793012114399);
  near(fit.chi2red, 811.4154457812723); near(fit.rms, .5306126922983224);
  near(fit.rmsBase, 1.6389190374575955); near(fit.worst.r, .4420154901395301);
});

test('header classifier excludes derived columns and reads measurement columns', () => {
  const header = ['distance_mm', 'reading 1', 'reading 2', 'mean_Oe', 'current_A'];
  assert.deepEqual(classifyHeader(header).measIdx, [1, 2]);
  const parsed = cellsToLines([header, ['4.5', '21.1', '21.2', '21.15', '1.0']]);
  assert.deepEqual(parsed.lines, ['4.5, 21.1, 21.2']);
});
